<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch, nextTick } from 'vue';
import { Plus, Upload, Search, ArrowLeft, Sparkles, Images, Check, X, Settings2, Layers, Trash2, Filter } from 'lucide-vue-next';
import UiButton from './UiButton.vue'; import UiBadge from './UiBadge.vue'; import UiDialog from './UiDialog.vue'; import RoomArt from './RoomArt.vue'; import AnnotationEditor from './AnnotationEditor.vue';
import AnnotationJob from './AnnotationJob.vue';
import UnassignedMedia from './UnassignedMedia.vue';
import ModelsPage from './ModelsPage.vue';
import TestPage from './TestPage.vue';
import DeployPage from './DeployPage.vue';
import AnalyticsPage from './AnalyticsPage.vue';
import ClassesTagsPage from './ClassesTagsPage.vue';
import { getPreview, batchColumn } from '../previewState.js';
import { liveAnnotate, loadBoard, loadSource, loadAssignment, loadReview, api as liveApi } from '../api/annotate.js';
import { FILTERS, loadDataset, loadVersions, datasetApi, recipeOf } from '../api/dataset.js';
import { loadTraining, trainApi, startKey, progressLine } from '../api/train.js';
const props = defineProps({page:String,project:Object,openAssignment:Number,openUpload:Number}); const emit=defineEmits(['navigate','create','opened','opened-upload']);
// Annotate reads the backend (api/annotate.js); the pages not connected yet keep the sample store.
const live=ref(null);
const LIVE_PAGES=['annotate','dataset','versions','train','models','test','deploy','analytics','classes'];
const state=computed(()=>LIVE_PAGES.includes(props.page)&&live.value?live.value:getPreview(props.project?.ref?`real:${props.project.ref}`:props.project?.id));
// The connected pages load from the backend when they open (after setup: they read refs declared below).
function syncLive(){if(!(LIVE_PAGES.includes(props.page)&&props.project?.ref))return;if(!live.value||live.value.ref!==props.project.ref)live.value=liveAnnotate(props.project.ref);if(props.page==='annotate')loadBoard(live.value).then(openWanted).catch(liveError);else if(props.page==='dataset')refreshDataset(1);else if(props.page==='train')loadTrain();else if(!['models','test','deploy','analytics','classes'].includes(props.page))loadVersions(live.value).catch(liveError);}
watch(()=>[props.page,props.project?.ref],syncLive);onMounted(syncLive);
watch(()=>props.page,()=>{message.value='';});   // a notification belongs to the page it was given on
async function refreshLive(){if(!live.value)return;await loadBoard(live.value);if(batch.value?.kind==='assignment'){const b=live.value.batches.find(x=>x.id===batch.value.id)||batch.value;batch.value=await loadAssignment(live.value,b);}if(reviewMode.value)await loadReview(live.value);}
function liveError(e){message.value=e.message;}
// Drag and drop on the board (asked for by the user on 2026-10-16). A drop runs the same backend step as the buttons:
// Unassigned→Annotating opens the batch on "Label with your team"; Annotating→In review submits it; In review→Dataset
// accepts it (after a confirmation); In review→Annotating sends it back and Annotating or In review→Unassigned rejects
// it (both with a reason). The Dataset is final, and a step is never skipped.
const dragging=ref(null);const dropOver=ref('');const moveDialog=ref(null);const moveReason=ref('');const moveBusy=ref(false);const choicesMode=ref('');
function dropRefusal(b,to){const from=batchColumn(b);if(!b||from===to)return '';
  if(from==='Dataset')return 'An accepted batch is final: its labels are approved and locked.';
  if(from==='Unassigned')return to==='Annotating'?'':'Give the batch to a labeller first: drop it on Annotating.';
  if(from==='Annotating')return to==='Dataset'?'A batch is reviewed before it enters the dataset: drop it on In review first.':'';
  return '';}
function dragStart(b,event){dragging.value=b;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',b.id);}
function dragEnd(){dragging.value=null;dropOver.value='';}
function dragOver(column,event){if(!dragging.value)return;event.preventDefault();dropOver.value=column;event.dataTransfer.dropEffect=dropRefusal(dragging.value,column)?'none':'move';}
async function dropOn(column){const b=dragging.value;dragEnd();if(!b||batchColumn(b)===column)return;const refused=dropRefusal(b,column);if(refused){message.value=refused;return;}
  if(!live.value){message.value='Preview only: a move is not saved here.';return;}
  message.value='';const from=batchColumn(b);
  if(from==='Unassigned'){choicesMode.value='team';await chooseBatch(b);return;}
  if(from==='Annotating'&&column==='In review')return moveNow(b,'return',{},`${b.name} is submitted for review.`);
  moveReason.value='';
  moveDialog.value=column==='Dataset'?{b,action:'accept',title:'Accept this batch',text:`The labels of ${b.name} are approved and locked, and its photos enter the dataset. This cannot be undone.`,reason:false,button:'Accept'}
    :column==='Annotating'?{b,action:'send-back',title:'Send back to the labeller',text:`${b.name} goes back to ${b.assignee} to label again.`,reason:true,button:'Send back'}
    :{b,action:'reject',title:'Reject this assignment',text:`${b.name} is closed without using its labels: they are kept, never enter a dataset version, and its photos go back to Unassigned.`,reason:true,button:'Reject'};}
async function moveNow(b,action,body,said){moveBusy.value=true;try{await liveApi.assignmentAction(live.value.ref,b.number,action,body);moveDialog.value=null;await refreshLive();tell(said);}
  catch(e){if(moveDialog.value)moveDialog.value.error=e.message;else message.value=e.message;}finally{moveBusy.value=false;}}
function confirmMove(){const d=moveDialog.value;if(!d||(d.reason&&!moveReason.value.trim()))return;
  moveNow(d.b,d.action,d.reason?{reason:moveReason.value.trim()}:{},d.action==='accept'?`${d.b.name} is accepted: its photos are in the dataset.`:d.action==='send-back'?`${d.b.name} is sent back to its labeller.`:`${d.b.name} is rejected; its photos are back in Unassigned.`);}
// An assignment a link names (a notification, an e-mail's button): opened once the board is loaded.
// After an upload, its batch opens on "Choose how to label this batch".
async function openUploaded(){const id=props.openUpload;if(!id||!live.value||props.page!=='annotate')return;emit('opened-upload');const b=live.value.batches.find(x=>x.kind==='upload'&&x.source===String(id));if(b)await chooseBatch(b);}
// A new assignment: its job page, or the editor at once ("Label manually", Auto Label).
function onAssigned(job,opts){batch.value=job;view.value='job';refreshLive().then(()=>{if(!opts?.edit)return;const images=state.value.images.filter(i=>i.batchId===job.id);if(images.length)openEditor(images.find(i=>!i.labelled)||images[0]);}).catch(liveError);}
async function openWanted(){if(props.openUpload&&!props.openAssignment)return openUploaded();const n=props.openAssignment;if(!n||!live.value||props.page!=='annotate')return;emit('opened');const b=live.value.batches.find(x=>x.kind==='assignment'&&x.number===n);if(b)await chooseBatch(b);else message.value=`Assignment ${n} is not on this project's board, or it is not yours to open.`;}
watch(()=>props.openAssignment,n=>{if(n&&live.value&&!live.value.loading&&live.value.ref===props.project?.ref)openWanted();});
const insight=computed(()=>props.page==='annotate'&&live.value?{images:live.value.photos??props.project?.images??0,accepted:live.value.counts.ready+live.value.counts.trained_on,annotations:live.value.counts.to_approve+live.value.counts.ready+live.value.counts.trained_on,toLabel:live.value.counts.to_label,live:true}:{images:state.value.images.length,accepted:accepted.value,annotations:annotations.value,toLabel:state.value.images.filter(i=>i.state==='Unlabeled').length,live:false});
async function renameBatch(){const name=draft.value.trim();if(!name){error.value='Enter a batch name.';return;}if(live.value&&props.page==='annotate'){try{if(batch.value.kind==='assignment')await liveApi.updateAssignment(live.value.ref,batch.value.number,{name});else await liveApi.renameUpload(live.value.ref,batch.value.source,name);batch.value.name=name;modal.value='';tell('Batch renamed');await loadBoard(live.value);}catch(e){error.value=e.message;}return;}batch.value.name=name;modal.value='';tell('Batch renamed');}
const view=ref('board');const query=ref('');const filter=ref('All');const modal=ref('');const draft=ref('');const message=ref('');const error=ref('');const picked=ref([]);const grid=ref(true);const overlays=ref(true);
const batch=ref(null);const editor=ref(false);const method=ref('');const model=ref('SAM 3 · masks');const prompt=ref('Outline room walls, windows and doors');const autoReady=ref(false);const modelTab=ref('Foundation models');const assignee=ref('Demo labeller');const reviewMode=ref(false);
const versionStep=ref(1);const versionName=ref('Version 1');const orient=ref(true);const resize=ref(true);const dimension=ref(640);const augmentation=ref(false);const split=ref('train_val');
const engine=ref('Custom training');const architecture=ref('RF-DETR');const size=ref('Small');const epochs=ref(50);const activeVersion=ref('');const resultReady=ref(false);const confidence=ref(0.5);const testSample=ref(false);const activeLimit=ref(100);const activeConfidence=ref(0.4);const ruleClass=ref('wall');const source=ref('Production model');
const images=computed(()=>props.page==='dataset'&&live.value&&props.project?.ref?state.value.images.filter(i=>i.batchId==='dataset'):state.value.images.filter(i=>(filter.value==='All'||i.state===filter.value)&&i.name.toLowerCase().includes(query.value.toLowerCase())));
const accepted=computed(()=>state.value.images.filter(i=>i.state==='Accepted'&&i.shapes.length>0).length);
const annotations=computed(()=>state.value.images.reduce((n,i)=>n+i.shapes.length,0));
const counts=computed(()=>state.value.classes.map(c=>({...c,count:state.value.images.reduce((n,i)=>n+i.shapes.filter(s=>s.kind===c.name).length,0)})));
watch(()=>props.page,()=>{view.value='board';query.value='';filter.value='All';message.value='';});
function tell(text){message.value=text;}
function openModal(name,value=''){modal.value=name;draft.value=value;error.value='';}
function openEditor(image){if(!state.value.images.length){tell('Add an image first');return;}state.value.selectedImage=image?.id||state.value.images[0].id;editor.value=true;}
async function chooseBatch(value){autoReady.value=false;if(live.value&&props.page==='annotate'){try{if(value.kind==='assignment'){batch.value=await loadAssignment(live.value,value);view.value='job';}else{await loadSource(live.value,value);batch.value=value;view.value='choices';}}catch(e){liveError(e);}return;}batch.value=value;view.value=batchColumn(value)==='Unassigned'?'choices':'job';}
async function goAuto(){modal.value='';emit('navigate','annotate');await nextTick();batch.value=state.value.batches[0]||null;view.value='auto';}
function beginManual(){if(batch.value){batch.value.status='Annotating';batch.value.assignee='Me';}view.value='job';}
function autoLabel(){if(!prompt.value.trim()){tell('Add a description before generating a preview');return;}autoReady.value=true;}
function applyAuto(){if(live.value&&props.page==='annotate'){tell('Auto label: coming soon. No labels were changed.');return;}state.value.images.filter(i=>(!batch.value||i.batchId===batch.value.id)&&i.state!=='Accepted').forEach(i=>{i.shapes=[{id:Date.now(),kind:state.value.classes[0]?.name||'wall',corner:'room',points:[[178,48],[460,48],[460,217],[178,217]]}];i.state='In review';});if(batch.value)batch.value.status='In review';tell('Sample annotations added to review queue');view.value='board';}
function markBatch(){const group=state.value.images.filter(i=>i.batchId===batch.value?.id);if(!group.length||group.some(i=>!i.shapes.length&&!i.noObjects)){tell('Label every image or mark no objects before accepting the batch');return;}group.forEach(i=>i.state='Accepted');batch.value.status='Dataset';view.value='board';tell('Batch accepted locally');}
async function makeVersion(){if(live.value&&props.page==='versions'){if(!versionName.value.trim()){tell('Enter a version name');return;}vBusy.value=true;try{const v=await datasetApi.publish(live.value.ref,{kind:split.value,title:versionName.value.trim(),recipe:recipeOf({resize:resize.value,dimension:dimension.value,augmentation:augmentation.value})});tell(`${v.name} created: ${v.photos} photo${v.photos===1?'':'s'}`);view.value='board';versionStep.value=1;versionName.value='';vPreview.value=null;await loadVersions(live.value);}catch(e){tell(e.message);}finally{vBusy.value=false;}return;}if(!versionName.value.trim()){tell('Enter a version name');return;}state.value.versions.unshift({id:Date.now(),name:versionName.value,images:accepted.value,split:split.value,resize:resize.value?dimension.value:'Original',orient:orient.value,augmentation:augmentation.value});view.value='board';versionStep.value=1;tell('Version configuration saved');}
// ── Dataset and Versions, connected (api/dataset.js) ──
const dsFilters=reactive({...FILTERS});const modalTargets=ref([]);const vPreview=ref(null);const vBusy=ref(false);
async function refreshDataset(page){if(!live.value)return;try{await loadDataset(live.value,{q:query.value,status:filter.value,filters:dsFilters,page:page||live.value.dataset?.page||1});picked.value=picked.value.filter(id=>state.value.images.some(i=>i.id===id&&i.batchId==='dataset'));}catch(e){liveError(e);}}
let dsTimer=null;watch([query,filter],()=>{if(props.page!=='dataset'||!live.value)return;clearTimeout(dsTimer);dsTimer=setTimeout(()=>refreshDataset(1),300);});
function resetFilters(){Object.assign(dsFilters,FILTERS);if(props.page==='dataset'&&live.value)refreshDataset(1);}
async function tagPicked(){const tag=draft.value.trim();if(!tag){error.value='Enter a tag.';return;}if(live.value&&props.page==='dataset'){try{const r=await datasetApi.tag(live.value.ref,picked.value,{add:tag});modal.value='';tell(r.full?`Tag added to ${r.changed}; ${r.full} already carry 20 tags`:`Tag added to ${r.changed} images`);await refreshDataset();}catch(e){error.value=e.message;}return;}state.value.images.filter(i=>picked.value.includes(i.id)).forEach(i=>{if(!i.tags.includes(tag))i.tags.push(tag)});modal.value='';tell('Tags added');}
async function toggleGolden(image){try{const r=await datasetApi.golden(live.value.ref,image.id,!image.golden);image.golden=r.golden;tell(r.golden?`${image.name} is in the golden set`:`${image.name} left the golden set`);}catch(e){liveError(e);}}
async function deleteTargets(){if(!draft.value.trim()){error.value='Give the reason for the deletion.';return;}try{const r=await datasetApi.remove(live.value.ref,modalTargets.value,draft.value);modal.value='';picked.value=[];tell(`${r.deleted} photo${r.deleted===1?'':'s'} deleted`+(r.affected_versions.length?`; the versions that held them keep them: ${r.affected_versions.join(', ')}`:''));await refreshDataset();}catch(e){error.value=e.message;}}
async function loadPreview(){if(props.page!=='versions'||!live.value||view.value!=='new-version'||!live.value.versionMeta?.canPublish)return;try{vPreview.value=await datasetApi.preview(live.value.ref,split.value);}catch(e){vPreview.value=null;liveError(e);}}
watch([split,view],loadPreview);
async function openVersion(v){try{const d=await datasetApi.version(live.value.ref,v.name);const {items,...card}=d;openModal('Version details',JSON.stringify({...card,photos_listed:items.length,deleted_since:items.filter(i=>i.deleted).length},null,2));}catch(e){liveError(e);}}
const splitWords={train:'Training',val:'Validation',test:'Test'};
// ── Train, connected (api/train.js): runs where the server trains (its CPU, or a GPU machine in the ML account: the
// options' device) ──
// On a CPU server a first run should end in minutes: 10 epochs and a size not marked slow, once (the person can change both).
let cpuDefaults=false;const runtime=ref(3600);const runView=ref(null);const runBusy=ref(false);let runTimer=null;
const onGpu=computed(()=>state.value?.training?.device==='cuda');
const trainsOn=computed(()=>onGpu.value?'a GPU machine in the ML account':'this server’s CPU');
const trainModel=computed(()=>(live.value?.training?.models||[]).find(m=>m.label===architecture.value));
async function loadTrain(){if(!live.value)return;try{const t=await loadTraining(live.value);runtime.value=t.default_runtime||3600;const names=(t.versions||[]).map(v=>v.name);if(!names.includes(activeVersion.value))activeVersion.value=names[0]||'';if(!(t.models||[]).some(m=>m.label===architecture.value))architecture.value='RF-DETR';const m=(t.models||[]).find(x=>x.label===architecture.value);if(m&&!m.sizes.includes(size.value))size.value=m.sizes[0];if(t.device==='cpu'&&!cpuDefaults){cpuDefaults=true;if(epochs.value===50)epochs.value=10;const quick=m?.sizes.find(x=>!(m.slow||[]).includes(x));if(quick)size.value=quick;}}catch(e){liveError(e);}}
watch(architecture,()=>{const m=trainModel.value;if(m&&!m.sizes.includes(size.value))size.value=m.sizes[0];});
function reviewTraining(){if(engine.value!=='Custom training'){tell('Neural architecture search: coming soon');return;}if(!(Number(epochs.value)>=1&&Number(epochs.value)<=500)){tell('Epochs must be between 1 and 500');return;}openModal('Review training');}
async function startTraining(){runBusy.value=true;try{const r=await trainApi.start(live.value.ref,{version:activeVersion.value,model:trainModel.value?.value,size:size.value,epochs:Number(epochs.value),max_runtime:Number(runtime.value),key:startKey()});modal.value='';tell(`Run ${r.number} started on ${r.version}`);await loadTrain();await openRun(r.number);}catch(e){modal.value='';tell(e.message);}finally{runBusy.value=false;}}
// An unfinished run is asked again every 5 seconds. One failed ask (a slow server) does not end the watching: the
// page keeps what it had and asks again.
async function openRun(number){clearTimeout(runTimer);const again=()=>{runTimer=setTimeout(()=>{if(view.value==='run'&&props.page==='train')openRun(number);},5000);};try{runView.value=await trainApi.run(live.value.ref,number);view.value='run';if(runView.value.unfinished)again();}catch(e){liveError(e);if(view.value==='run'&&runView.value?.number===number&&runView.value.unfinished)again();}}
function closeRun(){clearTimeout(runTimer);view.value='board';loadTrain();}
async function runAct(action){runBusy.value=true;try{await trainApi.act(live.value.ref,runView.value.number,action);await openRun(runView.value.number);loadTrain();}catch(e){tell(e.message);}finally{runBusy.value=false;}}
onUnmounted(()=>clearTimeout(runTimer));</script>
<template>
<div class="studio">
  <div v-if="message" class="notice" role="status"><Check :size="17"/><span>{{ message }}</span><button class="icon-button" aria-label="Dismiss feedback" @click="message=''"><X :size="16"/></button></div>
  <section v-if="!project?.ref" class="model-empty"><Layers :size="40"/><h2>Choose a project</h2><p>This page belongs to a project. Open one of your projects, or create one.</p><div class="studio-actions centred"><UiButton variant="primary" @click="emit('navigate','projects')">Open Projects</UiButton><UiButton @click="emit('create')"><Plus :size="16"/> New project</UiButton></div></section>
  <template v-else-if="page==='annotate'">
    <template v-if="view==='board'"><div class="studio-actions"><div class="studio-tabs"><button :class="{active:!reviewMode}" @click="reviewMode=false">Board</button><button :class="{active:reviewMode}" @click="reviewMode=true;if(live&&page==='annotate')loadReview(live).catch(liveError)">Review queue <UiBadge>{{ live&&page==='annotate'?live.counts.to_approve:state.images.filter(i=>i.state==='In review').length }}</UiBadge></button><button @click="view='insights'">Insights</button></div><UiButton @click="emit('navigate','upload')"><Upload :size="16"/> Upload images</UiButton></div>
      <p v-if="live&&page==='annotate'&&state.refused" class="field-error" role="note">{{ state.refused }}</p>
      <div v-if="reviewMode" class="media-grid"><button v-for="image in state.images.filter(i=>i.state==='In review'&&(!(live&&page==='annotate')||i.batchId==='review'))" :key="image.id" class="media-card" @click="openEditor(image)"><RoomArt v-if="image.sample" :variant="image.variant||0"/><img v-else :src="image.thumb||image.url" :alt="image.name" @error="image.thumb=''"><strong>{{ image.name }}</strong><UiBadge>In review</UiBadge></button><div v-if="!state.images.some(i=>i.state==='In review')" class="empty-state"><h2>No images awaiting review</h2><p>Finish labeling or apply a sample auto-label preview.</p></div></div>
      <div v-else class="annotation-board"><section v-for="column in ['Unassigned','Annotating','In review','Dataset']" :key="column" :class="{'drop-ok':dragging&&dropOver===column&&batchColumn(dragging)!==column&&!dropRefusal(dragging,column),'drop-no':dragging&&dropOver===column&&!!dropRefusal(dragging,column)}" @dragover="dragOver(column,$event)" @dragleave="dropOver===column&&(dropOver='')" @drop.prevent="dropOn(column)"><h3>{{ column }} <UiBadge>{{ state.batches.filter(b=>batchColumn(b)===column).length }}</UiBadge></h3><button v-for="b in state.batches.filter(b=>batchColumn(b)===column)" :key="b.id" :class="['batch-card',{dragging:dragging===b}]" :draggable="!!live" :title="live?'Drag to another column, or open it':''" @dragstart="dragStart(b,$event)" @dragend="dragEnd" @click="choicesMode='';chooseBatch(b)"><span v-if="b.code" class="batch-code">{{ b.code }}</span><strong>{{ b.name }}</strong><p>{{ b.count }} image{{ b.count===1?'':'s' }} · {{ b.group }}</p><div class="batch-progress"><span :style="{width:`${b.kind==='assignment'?(b.done||0)/Math.max(1,b.count)*100:state.images.filter(i=>i.batchId===b.id&&(i.shapes.length||i.noObjects)).length/Math.max(1,state.images.filter(i=>i.batchId===b.id).length)*100}%`}"/></div><footer><UiBadge>{{ b.assignee }}</UiBadge><span>Open batch →</span></footer></button><div v-if="!state.batches.some(b=>batchColumn(b)===column)" class="board-empty"><Images :size="27"/><p>{{ column==='Unassigned'?'No unassigned batches':column==='Annotating'?'Assign a batch to begin labeling':column==='In review'?'Labeled batches will appear here':'Approved batches appear here' }}</p><UiButton v-if="column==='Unassigned'" @click="emit('navigate','upload')">Upload</UiButton></div></section></div>
    </template>
    <AnnotationJob v-else-if="view==='job' && batch" :batch="batch" :state="state" @close="view='board';refreshLive().catch(liveError)" @choices="view='choices'" @edit="openEditor" @changed="refreshLive().catch(liveError)" @message="tell"/>
    <template v-else-if="view==='insights'"><UiButton @click="view='board'"><ArrowLeft :size="16"/> Back to board</UiButton><div class="metric-grid"><article><span>Images</span><strong>{{ insight.images }}</strong></article><article><span>Accepted</span><strong>{{ insight.accepted }}</strong></article><article><span>Annotations</span><strong>{{ insight.annotations }}</strong></article><article><span>To label</span><strong>{{ insight.toLabel }}</strong></article></div><section class="panel"><h2>Labeling progress</h2><p>{{ insight.live ? 'Counts of this project\'s photos and their labels.' : 'Counts reflect the local preview images.' }}</p><div class="distribution"><span :style="{width:`${insight.accepted/Math.max(1,insight.images)*100}%`}"/></div><p>{{ insight.accepted }} of {{ insight.images }} image{{ insight.images===1?'':'s' }} accepted</p></section></template>
    <UnassignedMedia v-else-if="view==='choices' && batch" :key="batch.id" :start-mode="choicesMode" :batch="batch" :state="state" :project="project" @close="view='board'" @upload="emit('navigate','upload')" @rename="openModal('Rename batch',batch.name)" @edit="openEditor" @auto="view='auto'" @professional="openModal('Professional labeling')" @assigned="onAssigned"/>
    <template v-else-if="view==='auto'"><UiButton @click="view='choices'"><ArrowLeft :size="16"/> Labeling choices</UiButton><div class="auto-layout"><section class="panel"><h2>Classes & prompts</h2><p>Describe the objects you want to label.</p><div v-for="c in state.classes" :key="c.name" class="class-prompt"><span :style="{background:c.color}"/><strong>{{ c.name }}</strong></div><label class="field-label">Visual description<textarea v-model="prompt" class="text-input" rows="4"/></label><UiButton @click="emit('navigate','classes')">Manage classes</UiButton><h3 class="section-title">Preview image</h3><RoomArt/><p>Sample image, not an inference result.</p></section><section class="panel"><h2>Choose a model</h2><div class="studio-tabs"><button v-for="t in ['Foundation models','My models','My workflows']" :key="t" :class="{active:modelTab===t}" @click="modelTab=t">{{ t }}</button></div><label v-for="name in modelTab==='Foundation models'?['SAM 3 · masks','SAM 3 · polygons','SAM 2 · point guided']:modelTab==='My models'?state.models.map(m=>m.name):state.workflows.map(w=>w.name)" :key="name" class="model-choice"><input v-model="model" name="autolabel-model" type="radio" :value="name"><div><strong>{{ name }}</strong><p>Preview selection · Coming soon</p></div></label><p v-if="modelTab!=='Foundation models' && !(modelTab==='My models'?state.models:state.workflows).length">No local {{ modelTab==='My models'?'models':'workflows' }} yet. Choose a foundation model to explore.</p><div class="studio-actions"><UiButton variant="primary" @click="autoLabel"><Sparkles :size="16"/> Generate sample preview</UiButton></div><div v-if="autoReady" class="auto-result"><UiBadge tone="purple">Illustrative prediction</UiBadge><RoomArt/><p>Sample wall polygon shown for review. No model was called.</p><UiButton variant="primary" @click="applyAuto">Apply sample labels to review queue</UiButton></div></section></div></template>
  </template>
  <template v-else-if="page==='dataset'">
    <div class="studio-actions"><div class="search-field"><Search :size="17"/><input v-model="query" aria-label="Search dataset" placeholder="Search images…"></div><select v-model="filter" class="compact-select" aria-label="Filter image status"><option>All</option><option>Unlabeled</option><option>Annotating</option><option>In review</option><option>Accepted</option><option>Changes requested</option></select><UiButton @click="openModal('Dataset filters')"><Filter :size="15"/> Filters</UiButton><UiButton @click="grid=!grid">{{ grid?'List view':'Grid view' }}</UiButton><UiButton variant="primary" @click="emit('navigate','versions')">Create version</UiButton></div><div class="studio-actions"><label><input v-model="overlays" type="checkbox"> Show annotations</label><span>{{ picked.length }} selected</span><UiButton :disabled="!picked.length" @click="openModal('Tag selected images')">Add tag</UiButton><UiButton :disabled="!picked.length" @click="picked=[]">Clear selection</UiButton><UiButton v-if="live&&page==='dataset'&&state.dataset?.may?.delete" :disabled="!picked.length" @click="modalTargets=[...picked];openModal('Delete photos')"><Trash2 :size="14"/> Delete selected</UiButton><span v-if="live&&page==='dataset'&&state.dataset?.splitCounts">Training {{ state.dataset.splitCounts.train||0 }} · Validation {{ state.dataset.splitCounts.val||0 }} · Test {{ state.dataset.splitCounts.test||0 }} · Unassigned {{ state.dataset.splitCounts.unassigned||0 }}</span></div><div v-if="images.length" :class="['media-grid',{'media-list':!grid}]"><article v-for="image in images" :key="image.id" class="media-card"><div class="media-visual"><button @click="openEditor(image)"><RoomArt v-if="image.sample" :variant="image.variant||0"/><img v-else :src="image.thumb||image.url" :alt="image.name" @error="image.thumb=''"><span v-if="overlays&&(image.labels??image.shapes.length)" class="image-label">{{ image.labels??image.shapes.length }} labels</span></button><input v-model="picked" type="checkbox" :value="image.id" :aria-label="`Select ${image.name}`"></div><strong>{{ image.name }}</strong><UiBadge :tone="image.state==='Accepted'?'green':'neutral'">{{ image.state }}</UiBadge><p>{{ image.tags.join(', ') }}</p><template v-if="live&&page==='dataset'"><small>{{ image.group?(splitWords[image.split]||'Unassigned'):'Unassigned pool' }}{{ image.group?` · ${image.group}`:'' }}{{ image.golden?' · Golden':'' }}</small><div class="studio-actions"><UiButton v-if="state.dataset?.may?.golden" @click="toggleGolden(image)">{{ image.golden?'Leave golden set':'Make golden' }}</UiButton><UiButton v-if="state.dataset?.may?.delete" @click="modalTargets=[image.id];openModal('Delete photos')"><Trash2 :size="14"/> Delete</UiButton></div></template></article></div><div v-else class="empty-state"><Images :size="30"/><h2>No images here yet</h2><p>Upload images or clear the filters to explore the dataset.</p><UiButton @click="query='';filter='All';resetFilters()">Clear filters</UiButton><UiButton @click="emit('navigate','upload')">Upload images</UiButton></div><footer class="studio-pagination"><template v-if="live&&page==='dataset'">{{ state.dataset?.total??0 }} images · page {{ state.dataset?.page||1 }} of {{ state.dataset?.pages||1 }} <UiButton :disabled="(state.dataset?.page||1)<=1" @click="refreshDataset(state.dataset.page-1)">Previous</UiButton> <UiButton :disabled="(state.dataset?.page||1)>=(state.dataset?.pages||1)" @click="refreshDataset(state.dataset.page+1)">Next</UiButton></template><template v-else>{{ images.length }} image{{ images.length===1?'':'s' }} · Preview collection</template></footer>
  </template>
  <ClassesTagsPage v-else-if="page==='classes'" :project-ref="project.ref" @navigate="p=>emit('navigate',p)"/>
  <template v-else-if="page==='versions'">
    <div v-if="view!=='new-version'"><div class="studio-actions"><p>Freeze a reproducible dataset configuration for training or evaluation.</p><UiButton v-if="!(live&&page==='versions')||state.versionMeta?.canPublish" variant="primary" :disabled="!!(live&&page==='versions'&&state.versionMeta?.refused)" @click="view='new-version';versionStep=1"><Plus :size="16"/> New version</UiButton></div><p v-if="live&&page==='versions'&&state.versionMeta?.refused" class="field-error">{{ state.versionMeta.refused }}</p><div v-if="state.versions.length" class="choice-grid"><template v-if="live&&page==='versions'"><article v-for="v in state.versions" :key="v.name" class="panel"><UiBadge tone="green">{{ v.kind_label }}</UiBadge><h2>{{ v.title||v.name }}</h2><p>{{ v.photos }} photos · {{ v.name }}</p><p>Training {{ v.split_counts.train||0 }} · Validation {{ v.split_counts.val||0 }} · Test {{ v.split_counts.test||0 }}</p><p>Resize: {{ v.recipe.resize?`${v.recipe.resize} × ${v.recipe.resize}`:'Original' }} · Auto-orient: On{{ v.recipe.augment?' · Flip and brightness':'' }}</p><p v-if="v.untrainable" class="field-error">{{ v.untrainable }}</p><p v-if="v.deleted">{{ v.deleted }} of its photos were deleted on request since.</p><UiButton :disabled="!state.versionMeta?.kinds?.find(k=>k.value===v.kind)?.training||!!v.untrainable" @click="activeVersion=v.name;emit('navigate','train')">Use for training</UiButton><UiButton @click="openVersion(v)">View configuration</UiButton><a class="button button--secondary" :href="v.manifest" download>Manifest</a></article></template><template v-else><article v-for="v in state.versions" :key="v.id" class="panel"><UiBadge tone="green">Local configuration</UiBadge><h2>{{ v.name }}</h2><p>{{ v.images }} accepted images · {{ v.split }}</p><p>Resize: {{ v.resize }} · Auto-orient: {{ v.orient?'On':'Off' }}</p><UiButton @click="activeVersion=String(v.id);emit('navigate','train')">Use for training</UiButton><UiButton @click="openModal('Version details',JSON.stringify(v,null,2))">View configuration</UiButton></article></template></div><div v-else class="empty-state"><Layers :size="32"/><h2>No versions yet</h2><p>Create your first version from accepted images.</p><UiButton variant="primary" @click="view='new-version';versionStep=1">Create a version</UiButton></div></div>
    <div v-else class="version-builder"><aside><h3>New version</h3><button v-for="(label,i) in ['Source images','Split rules','Preprocessing','Augmentation','Review & create']" :key="label" :class="{active:versionStep===i+1}" @click="versionStep=i+1"><span>{{ i+1 }}</span>{{ label }}</button></aside><section class="panel"><template v-if="versionStep===1"><h2>Source images</h2><p v-if="live&&page==='versions'&&vPreview&&!vPreview.photos" class="field-error">{{ vPreview.empty||'No photo can go into this version yet.' }}</p><p v-if="live&&page==='versions'">{{ vPreview?`${vPreview.photos} photos with an approved label can go into this version (${vPreview.new} new since ${vPreview.latest||'the start'}).`:'Counting…' }}</p><p v-else>{{ accepted }} accepted images from {{ state.images.length }} total images.</p><label class="field-label">Version name<input v-model="versionName" class="text-input" maxlength="80"></label><p>Only accepted labeled images are eligible. No-object examples remain excluded from training versions under the existing workflow.</p><UiButton @click="emit('navigate','dataset')">Inspect dataset</UiButton></template><template v-else-if="versionStep===2"><h2>Train / validation / test</h2><template v-if="live&&page==='versions'"><p>Every photo of one home or group stays on the same side. The side is fixed when the photo arrives (about 70 / 15 / 15), never chosen by hand. This is what the version will hold:</p><div class="split-bar"><span>Train {{ vPreview?.split_counts?.train||0 }}</span><span>Valid {{ vPreview?.split_counts?.val||0 }}</span><span>Test {{ vPreview?.split_counts?.test||0 }}</span></div></template><template v-else><p>Related home/group images stay together. The proportions below are illustrative; no image split is computed in this prototype.</p><div class="split-bar"><span>Train ~70%</span><span>Valid ~15%</span><span>Test ~15%</span></div></template><label class="field-label">Version purpose<select v-model="split" class="text-input"><option value="train_val">Training / validation</option><option value="test">Test evaluation only</option><option value="golden">Golden evaluation only</option><option value="smoke">Smoke check</option></select></label><p>Test and golden versions must not be used for training.</p></template><template v-else-if="versionStep===3"><h2>Preprocessing</h2><p>Configure how images are prepared before training.</p><label class="setting-row"><input v-model="orient" type="checkbox" :disabled="live&&page==='versions'"> Auto-orient images<template v-if="live&&page==='versions'"> (always: photos are turned upright when they arrive)</template></label><label class="setting-row"><input v-model="resize" type="checkbox"> Resize images</label><label v-if="resize" class="field-label">Target size<select v-model="dimension" class="text-input"><option :value="512">512 × 512</option><option :value="640">640 × 640</option><option :value="1024">1024 × 1024</option></select><small class="field-help">Training uses the nearest size the model accepts (a multiple of its patch size): 640 trains at 648 with RF-DETR.</small></label><RoomArt class="version-preview"/><p v-if="live&&page==='versions'">The size is used when a model trains on this version, rounded to the nearest size that model accepts.</p><p v-else>Illustration only; image processing is not connected.</p></template><template v-else-if="versionStep===4"><h2>Augmentation</h2><p>Explore training-only transformations. Validation and test images remain unaugmented.</p><label class="setting-row"><input v-model="augmentation" type="checkbox"> Horizontal flip and brightness variation</label><div class="augmentation-previews"><RoomArt/><RoomArt :style="{transform:'scaleX(-1)',filter:'brightness(1.1)'}"/></div></template><template v-else><h2>Review version</h2><dl class="summary-list"><dt>Name</dt><dd>{{ versionName }}</dd><dt>Source</dt><dd>{{ live&&page==='versions'?`${vPreview?.photos??0} photos with an approved label`:`${accepted} accepted images` }}</dd><dt>Purpose</dt><dd>{{ split }}</dd><dt>Preprocessing</dt><dd>{{ orient?'Auto-orient · ':'' }}{{ resize?`${dimension} × ${dimension}`:'Original size' }}</dd><dt>Augmentation</dt><dd>{{ augmentation?'Flip and brightness (training only)':'None' }}</dd></dl><template v-if="live&&page==='versions'&&vPreview"><p>{{ vPreview.photos }} photos: {{ vPreview.new }} new, {{ vPreview.kept }} kept from {{ vPreview.latest||'no earlier version' }}.</p><p v-if="vPreview.unchanged" class="field-error">Nothing changed since {{ vPreview.latest }}: the same photos with the same labels.</p><p v-if="vPreview.untrainable" class="field-error">{{ vPreview.untrainable }}</p><p v-if="!vPreview.photos" class="field-error">{{ vPreview.empty||'No photo can go into this version yet.' }}</p></template><UiBadge v-if="!(live&&page==='versions')">Coming soon</UiBadge></template><div class="wizard-footer"><UiButton @click="versionStep>1?versionStep--:view='board'">{{ versionStep>1?'Back':'Cancel' }}</UiButton><UiButton v-if="versionStep<5" variant="primary" @click="versionStep++">Continue</UiButton><UiButton v-else variant="primary" :disabled="vBusy||!!(live&&page==='versions'&&(!vPreview||vPreview.unchanged||!vPreview.photos))" :title="live&&page==='versions'&&!vPreview?'Waiting for the preview of what the version will hold':''" @click="makeVersion">{{ live&&page==='versions'?(vBusy?'Creating…':'Create version'):'Create local version' }}</UiButton></div></section></div>
  </template>
  <AnalyticsPage v-else-if="page==='analytics'" :project-ref="project.ref"/>
  <ModelsPage v-else-if="page==='models'" :project-ref="project.ref" @navigate="p=>emit('navigate',p)"/>
  <template v-else-if="page==='train'&&view==='run'&&runView"><UiButton @click="closeRun"><ArrowLeft :size="16"/> Back to training</UiButton><section class="panel training-config"><h2>Run {{ runView.number }} · {{ runView.trains.summary }}</h2><p><UiBadge :tone="runView.state==='succeeded'?'green':'purple'">{{ runView.state_label }}</UiBadge> {{ runView.version_title?`${runView.version_title} · `:'' }}{{ runView.version }} · started by {{ runView.by }} · {{ new Date(runView.created_at).toLocaleString() }}</p><template v-if="progressLine(runView.progress)"><div class="distribution"><span :style="{width:`${progressLine(runView.progress).share*100}%`}"/></div><p>{{ progressLine(runView.progress).text }}</p></template><p v-else-if="runView.unfinished">{{ runView.state==='queued'?(onGpu?'Waiting for a GPU machine: one run trains at a time.':'Waiting for the CPU: one run trains at a time.'):'Starting…' }}</p><p v-if="runView.failure" class="field-error">{{ runView.failure }}</p><dl v-if="Object.keys(runView.final_metrics||{}).length" class="summary-list"><template v-for="(value,name) in runView.final_metrics" :key="name"><dt>{{ name }}</dt><dd>{{ typeof value==='number'?value.toFixed(4):value }}</dd></template></dl><p v-if="runView.model">It made model {{ runView.model.version }}.</p><div class="studio-actions"><UiButton v-if="runView.may.cancel" :disabled="runBusy" @click="runAct('cancel')">Cancel run</UiButton><UiButton v-if="runView.may.retry" variant="primary" :disabled="runBusy" @click="runAct('retry')">Retry</UiButton><a v-for="a in runView.attempts" :key="a.number" class="button button--secondary" :href="a.log" download>Log of attempt {{ a.number }}</a></div><h3>Log</h3><pre class="code-block">{{ runView.log||'Nothing written yet.' }}</pre></section></template><template v-else-if="page==='train'"><h2>Select a training engine</h2><p class="section-description">Choose your configuration, review the dataset, and explore the resulting job screen.</p><div class="choice-grid"><button :class="{chosen:engine==='Custom training'}" @click="engine='Custom training'"><Settings2 :size="26"/><h3>Custom training</h3><p>Select architecture, model size and training settings.</p></button><button :class="{chosen:engine==='Neural architecture search'}" @click="engine='Neural architecture search'"><Sparkles :size="26"/><h3>Neural architecture search</h3><p>Explore a search across model sizes and accuracy/latency targets.</p><UiBadge>Coming soon</UiBadge></button></div><section class="panel training-config"><h2>Training configuration</h2><div class="form-grid"><label class="field-label">Dataset version<select v-if="live&&page==='train'" v-model="activeVersion" class="text-input"><option v-if="!state.training?.versions?.length" value="">No version can be trained yet</option><option v-for="v in state.training?.versions||[]" :key="v.name" :value="v.name">{{ v.title?`${v.title} · `:'' }}{{ v.name }} · {{ v.photos }} photos</option></select><select v-else v-model="activeVersion" class="text-input"><option value="">Sample version (preview only)</option><option v-for="v in state.versions" :key="v.id" :value="String(v.id)" :disabled="['test','golden'].includes(v.split)">{{ v.name }} · {{ v.split }}</option></select></label><label class="field-label">Architecture<select v-model="architecture" class="text-input"><option>RF-DETR</option><option v-if="live&&page==='train'">Aadml-Vision-seg-A0</option><option value="YOLO" :disabled="live&&page==='train'">YOLO{{ live&&page==='train'?' (Coming soon)':'' }}</option><option value="Custom architecture" :disabled="live&&page==='train'">Custom architecture{{ live&&page==='train'?' (Coming soon)':'' }}</option></select></label><label class="field-label">Model size<select v-model="size" class="text-input"><template v-if="live&&page==='train'&&trainModel"><option v-for="s in trainModel.sizes" :key="s" :value="s">{{ s }}{{ trainModel.slow.includes(s)?' (slow on a CPU: hours)':'' }}</option></template><template v-else><option>Nano</option><option>Small</option><option>Medium</option><option>Large</option></template></select></label><label class="field-label">Epochs<input v-model="epochs" class="text-input" type="number" min="1" max="500"></label><label v-if="live&&page==='train'" class="field-label">Maximum runtime<select v-model="runtime" class="text-input"><option v-for="r in state.training?.runtimes||[]" :key="r.value" :value="r.value">{{ r.label }}</option></select></label></div><template v-if="live&&page==='train'"><p>Runs on {{ trainsOn }} and stops at its time limit. Test and golden versions are never trained on.{{ trainModel?.research_only?' Aadml-Vision-seg-A0 is for research and evaluation only (an NVIDIA research licence): a model trained from it is never released to an app.':'' }}{{ trainModel?.slow?.includes(size)?' This size is slow on a CPU: expect hours.':'' }}</p><p v-if="state.training?.refused" class="field-error">{{ state.training.refused }}</p><p v-else-if="state.training?.no_version" class="field-error">{{ state.training.no_version }}</p><p v-else-if="state.training&&!state.training.can_train" class="field-error">Your role in this project does not let you start a run.</p></template><p v-else>Test and golden versions are unavailable for training. No compute, credits or infrastructure will be used.</p><UiButton variant="primary" :disabled="live&&page==='train'&&(!!state.training?.refused||!state.training?.can_train||!activeVersion)" @click="live&&page==='train'?reviewTraining():(Number(epochs)>=1&&Number(epochs)<=500?openModal('Review training'):tell('Epochs must be between 1 and 500'))">Review training configuration</UiButton></section><section v-if="live&&page==='train'&&state.training?.runs?.length" class="panel training-config"><h2>Runs</h2><div v-for="r in state.training.runs" :key="r.number" class="stat-row"><strong>Run {{ r.number }} · {{ r.trains.summary }} · {{ r.version }}</strong><UiBadge :tone="r.state==='succeeded'?'green':'purple'">{{ r.state_label }}</UiBadge><UiButton @click="openRun(r.number)">View run</UiButton></div></section><section v-else-if="state.runs.length" class="panel training-config"><h2>Preview runs</h2><div v-for="r in state.runs" :key="r.id" class="stat-row"><strong>{{ r.name }}</strong><UiBadge tone="purple">{{ r.status }}</UiBadge><UiButton @click="emit('navigate','models')">View result</UiButton></div></section></template>
  <TestPage v-else-if="page==='test'" :project-ref="project.ref" @navigate="p=>emit('navigate',p)"/>
  <section v-else-if="page==='nas'||page==='active'" class="model-empty"><Layers :size="40"/><UiBadge tone="purple">Coming soon</UiBadge><h2>{{ page==='nas' ? 'Neural architecture search' : 'Active learning' }}</h2><p>{{ page==='nas' ? 'Trying many model sizes and shapes to find the best balance of speed and accuracy needs GPU machines, which this server does not have yet. Train a model on the Train page meanwhile.' : 'Keeping the photos your deployed model was unsure of, to label and train on next, means keeping your customers\' prediction photos. That needs your decision on how they may be kept before it is built.' }}</p><UiButton @click="emit('navigate', page==='nas' ? 'train' : 'deploy')">{{ page==='nas' ? 'Open Train' : 'Open Deployments' }}</UiButton></section>
  <DeployPage v-else-if="page==='deploy'" :project-ref="project.ref" @navigate="p=>emit('navigate',p)"/>
  <AnnotationEditor v-if="editor" :state="state" :batch-id="['job','choices'].includes(view)?batch?.id:(page==='dataset'&&live?'dataset':(reviewMode&&live&&page==='annotate'?'review':null))" @close="editor=false;page==='dataset'?refreshDataset():refreshLive().catch(liveError)"/>
  <UiDialog :open="!!moveDialog" :title="moveDialog?.title" @close="moveDialog=null"><template v-if="moveDialog"><p class="dialog-description">{{ moveDialog.text }}</p><label v-if="moveDialog.reason" class="field-label">Reason<textarea v-model="moveReason" class="text-input" rows="3" maxlength="1000"/></label><p v-if="moveDialog.error" class="field-error" role="alert">{{ moveDialog.error }}</p><div class="dialog-actions"><UiButton @click="moveDialog=null">Cancel</UiButton><UiButton variant="primary" :disabled="moveBusy||(moveDialog.reason&&!moveReason.trim())" @click="confirmMove">{{ moveDialog.button }}</UiButton></div></template></UiDialog><UiDialog :open="!!modal" :title="modal" @close="modal=''">
    <p v-if="error" class="field-error" role="alert">{{ error }}</p>
    <template v-if="modal==='Rename batch'"><label class="field-label">Batch name<input v-model="draft" class="text-input"></label><UiButton @click="renameBatch">Save name</UiButton></template>
    <template v-else-if="modal==='Assign labeling'"><label class="field-label">Assign to<select v-model="assignee" class="text-input"><option>Demo labeller</option><option>Demo reviewer</option><option>Me</option></select></label><label class="field-label">Instructions<textarea v-model="draft" class="text-input" placeholder="Outline walls, windows and doors; review all corners."/></label><p class="dialog-description">No invitation or notification will be sent.</p><div class="dialog-actions"><UiButton variant="primary" @click="batch.instructions=draft;batch.assignee=assignee;batch.status='Annotating';modal='';view='board';tell('Sample assignment saved')">Assign locally</UiButton></div></template>
    <template v-else-if="modal==='Professional labeling'"><label class="field-label">Labeling brief<textarea v-model="draft" class="text-input" rows="4" placeholder="Describe classes, quality requirements and review criteria."/></label><p class="dialog-description">Coming soon. No vendor is contacted and no images leave this browser.</p><UiButton @click="draft.trim()?(batch.brief=draft.trim(),modal='',tell('Labeling brief preview saved')):error='Enter a labeling brief.'">Save local brief</UiButton></template>
    <template v-else-if="modal==='Tag selected images'"><label class="field-label">Tag<input v-model="draft" class="text-input"></label><UiButton @click="tagPicked">Apply to {{ picked.length }} image{{ picked.length===1?'':'s' }}</UiButton></template>
    <template v-else-if="modal==='Dataset filters'&&live&&page==='dataset'"><label class="field-label">Status<select v-model="filter" class="text-input"><option>All</option><option>Unlabeled</option><option>Annotating</option><option>In review</option><option>Changes requested</option><option>Accepted</option></select></label><label class="field-label">Split<select v-model="dsFilters.split" class="text-input"><option value="">All</option><option value="train">Training</option><option value="val">Validation</option><option value="test">Test</option><option value="unassigned">Unassigned pool</option></select></label><label class="field-label">Home / group<input v-model="dsFilters.group" class="text-input" maxlength="200"></label><label class="field-label">Image source<select v-model="dsFilters.origin" class="text-input"><option value="">All</option><option value="development">Development / test images</option><option value="customer">Customer images</option></select></label><label class="field-label">Golden set<select v-model="dsFilters.golden" class="text-input"><option value="">All</option><option value="true">In the golden set</option><option value="false">Not golden</option></select></label><label class="field-label">Tag<input v-model="dsFilters.tag" class="text-input" maxlength="40"></label><div class="dialog-actions"><UiButton @click="resetFilters();modal=''">Clear</UiButton><UiButton variant="primary" @click="refreshDataset(1);modal=''">Apply filter</UiButton></div></template><template v-else-if="modal==='Dataset filters'"><label class="field-label">Status<select v-model="filter" class="text-input"><option>All</option><option>Unlabeled</option><option>In review</option><option>Accepted</option></select></label><p class="dialog-description">Filter the current local preview collection.</p><UiButton @click="modal=''">Apply filter</UiButton></template><template v-else-if="modal==='Delete photos'"><p class="dialog-description">{{ modalTargets.length }} photo{{ modalTargets.length===1?'':'s' }} will be deleted: the stored copy and the records that brought it go, and it can never be taken in again. Versions that already hold it keep it, and are listed with the deletion.</p><label class="field-label">Reason (required)<textarea v-model="draft" class="text-input" rows="3" maxlength="500" placeholder="For example: the customer asked for it."/></label><div class="dialog-actions"><UiButton @click="modal=''">Cancel</UiButton><UiButton variant="primary" @click="deleteTargets">Delete</UiButton></div></template>
    <template v-else-if="modal==='Version details'"><pre>{{ draft }}</pre><UiButton @click="modal=''">Close</UiButton></template>
    <template v-else-if="modal==='Review training'"><dl class="summary-list"><dt>Engine</dt><dd>{{ engine }}</dd><dt>Model</dt><dd>{{ architecture }} {{ size }}</dd><dt>Epochs</dt><dd>{{ epochs }}</dd><dt>Version</dt><dd>{{ live&&page==='train'?activeVersion:(state.versions.find(v=>String(v.id)===activeVersion)?.name||'Sample version') }}</dd><template v-if="live&&page==='train'"><dt>Maximum runtime</dt><dd>{{ (state.training?.runtimes||[]).find(r=>r.value===Number(runtime))?.label }}</dd><dt>Runs on</dt><dd>{{ onGpu?'A GPU machine in the ML account':'This server’s CPU' }}</dd></template></dl><p class="dialog-description">{{ live&&page==='train'?`Starts a training run on ${trainsOn}. It stops at the time limit you chose.`:'This action only adds a simulated result. No training, deployment or billing action occurs.' }}</p><div class="dialog-actions"><UiButton @click="modal=''">Back</UiButton><UiButton variant="primary" :disabled="runBusy" @click="startTraining()">{{ runBusy?'Starting…':'Start training' }}</UiButton></div></template>
  </UiDialog>
</div>
</template>
